import{_ as a,a0 as s,w as l,s as i,I as o,x as t,a1 as e,A as p,ao as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"CPU 电源管理器：Linux 系统中 CPU 主频的控制和管理 | LCTT x X-CMD","titleTemplate":false,"description":"CPU 电源管理器：Linux 系统中 CPU 主频的控制和管理 | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"CPU 电源管理器：Linux 系统中 CPU 主频的控制和管理 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"CPU 电源管理器：Linux 系统中 CPU 主频的控制和管理 | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20180926 CPU Power Manager - Control And Manage CPU Frequency In Linux","title":"CPU 电源管理器：Linux 系统中 CPU 主频的控制和管理","tag":"201810","desc":""},"relativePath":"201810/20180926 CPU Power Manager - Control And Manage CPU Frequency In Linux.md","filePath":"[post].md"}'),P={name:"201810/20180926 CPU Power Manager - Control And Manage CPU Frequency In Linux.md"};function g(C,n,w,d,m,x){const r=s("Link");return l(),i("div",null,[n[27]||(n[27]=o("h1",{id:"cpu-电源管理器-linux-系统中-cpu-主频的控制和管理",tabindex:"-1"},[t("CPU 电源管理器：Linux 系统中 CPU 主频的控制和管理 "),o("a",{class:"header-anchor",href:"#cpu-电源管理器-linux-系统中-cpu-主频的控制和管理","aria-label":"Permalink to “CPU 电源管理器：Linux 系统中 CPU 主频的控制和管理”"},"​")],-1)),n[28]||(n[28]=o("p",null,[o("img",{src:"https://www.ostechnix.com/wp-content/uploads/2018/09/Manage-CPU-Frequency-720x340.jpeg",alt:""})],-1)),o("p",null,[n[1]||(n[1]=t("你使用笔记本的话，可能知道 Linux 系统的电源管理做的很不好。虽然有 ",-1)),n[2]||(n[2]=o("strong",null,"TLP",-1)),n[3]||(n[3]=t("、",-1)),e(r,{href:"https://www.ostechnix.com/improve-laptop-battery-performance-linux/"},{default:p(()=>[...n[0]||(n[0]=[o("strong",null,"Laptop Mode Tools",-1),t(" 和 ",-1),o("strong",null,"powertop",-1)])]),_:1}),n[4]||(n[4]=t(" 这些工具来辅助减少电量消耗，但跟 Windows 和 Mac OS 系统比较起来，电池的整个使用周期还是不尽如意。此外，还有一种降低功耗的办法就是限制 CPU 的频率。这是可行的，然而却需要编写很复杂的终端命令来设置，所以使用起来不太方便。幸好，有一款名为 ",-1)),n[5]||(n[5]=o("strong",null,"CPU Power Manager",-1)),n[6]||(n[6]=t(" 的 GNOME 扩展插件，可以很容易的就设置和管理你的 CPU 主频。GNOME 桌面系统中，CPU Power Manager 使用名为 ",-1)),n[7]||(n[7]=o("strong",null,"intel_pstate",-1)),n[8]||(n[8]=t(" 的频率调整驱动程序（几乎所有的 Intel CPU 都支持）来控制和管理 CPU 主频。",-1))]),n[29]||(n[29]=o("p",null,"使用这个扩展插件的另一个原因是可以减少系统的发热量，因为很多系统在正常使用中的发热量总让人不舒服，限制 CPU 的主频就可以减低发热量。它还可以减少 CPU 和其他组件的磨损。",-1)),n[30]||(n[30]=o("h3",{id:"安装-cpu-power-manager",tabindex:"-1"},[t("安装 CPU Power Manager "),o("a",{class:"header-anchor",href:"#安装-cpu-power-manager","aria-label":"Permalink to “安装 CPU Power Manager”"},"​")],-1)),o("p",null,[n[10]||(n[10]=t("首先，进入",-1)),e(r,{href:"https://extensions.gnome.org/extension/945/cpu-power-manager/"},{default:p(()=>[...n[9]||(n[9]=[t("扩展插件主页面",-1)])]),_:1}),n[11]||(n[11]=t("，安装此扩展插件。",-1))]),n[31]||(n[31]=u('<p>安装好插件后，在 GNOME 顶部栏的右侧会出现一个 CPU 图标。点击图标，会出现安装此扩展一个选项提示，如下示：</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/09/CPU-Power-Manager-icon.png" alt=""></p><p>点击“尝试安装”按纽，会弹出输入密码确认框。插件需要 root 权限来添加 policykit 规则，进而控制 CPU 主频。下面是弹出的提示框样子：</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/09/CPU-Power-Manager-1.png" alt=""></p><p>输入密码，点击“认证”按纽，完成安装。最后在 <code>/usr/share/polkit-1/actions</code> 目录下添加了一个名为 <code>mko.cpupower.setcpufreq.policy</code> 的 policykit 文件。</p><p>都安装完成后，如果点击右上脚的 CPU 图标，会出现如下所示：</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/09/CPU-Power-Manager.png" alt=""></p><h3 id="功能特性" tabindex="-1">功能特性 <a class="header-anchor" href="#功能特性" aria-label="Permalink to “功能特性”">​</a></h3><ul><li><strong>查看 CPU 主频：</strong> 显然，你可以通过这个提示窗口看到 CPU 的当前运行频率。</li><li><strong>设置最大、最小主频：</strong> 使用此扩展，你可以根据列出的最大、最小频率百分比进度条来分别设置其频率限制。一旦设置，CPU 将会严格按照此设置范围运行。</li><li><strong>开/关 Turbo Boost：</strong> 这是我最喜欢的功能特性。大多数 Intel CPU 都有 “Turbo Boost” 特性，为了提高额外性能，其中的一个内核为自动进行超频。此功能虽然可以使系统获得更高的性能，但也大大增加功耗。所以，如果不做 CPU 密集运行的话，为节约电能，最好关闭 Turbo Boost 功能。事实上，在我电脑上，我大部分时间是把 Turbo Boost 关闭的。</li><li><strong>生成配置文件：</strong> 可以生成最大和最小频率的配置文件，就可以很轻松打开/关闭，而不是每次手工调整设置。</li></ul><h3 id="偏好设置" tabindex="-1">偏好设置 <a class="header-anchor" href="#偏好设置" aria-label="Permalink to “偏好设置”">​</a></h3><p>你也可以通过偏好设置窗口来自定义扩展插件显示形式：</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/09/CPU-Power-Manager-preferences.png" alt=""></p><p>如你所见，你可以设置是否显示 CPU 主频，也可以设置是否以 <strong>Ghz</strong> 来代替 <strong>Mhz</strong> 显示。</p><p>你也可以编辑和创建/删除配置文件：</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/09/CPU-Power-Manager-preferences-1.png" alt=""></p><p>可以为每个配置文件分别设置最大、最小主频及开/关 Turbo boost。</p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>正如我在开始时所说的，Linux 系统的电源管理并不是最好的，许多人总是希望他们的 Linux 笔记本电脑电池能多用几分钟。如果你也是其中一员，就试试此扩展插件吧。为了省电，虽然这是非常规的做法，但有效果。我确实喜欢这个插件，到现在已经使用了好几个月了。</p><p>你对此插件有何看法呢？请把你的观点留在下面的评论区吧。</p><p>祝贺!</p><hr>',21)),o("p",null,[n[13]||(n[13]=t("via: ",-1)),e(r,{href:"https://www.ostechnix.com/cpu-power-manager-control-and-manage-cpu-frequency-in-linux/"},{default:p(()=>[...n[12]||(n[12]=[t("https://www.ostechnix.com/cpu-power-manager-control-and-manage-cpu-frequency-in-linux/",-1)])]),_:1})]),o("p",null,[n[18]||(n[18]=t("作者：",-1)),e(r,{href:"https://www.ostechnix.com/author/editor/"},{default:p(()=>[...n[14]||(n[14]=[t("EDITOR",-1)])]),_:1}),n[19]||(n[19]=t(" 选题：",-1)),e(r,{href:"https://github.com/lujun9972"},{default:p(()=>[...n[15]||(n[15]=[t("lujun9972",-1)])]),_:1}),n[20]||(n[20]=t(" 译者：",-1)),e(r,{href:"https://github.com/runningwater"},{default:p(()=>[...n[16]||(n[16]=[t("runningwater",-1)])]),_:1}),n[21]||(n[21]=t(" 校对：",-1)),e(r,{href:"https://github.com/wxy"},{default:p(()=>[...n[17]||(n[17]=[t("wxy",-1)])]),_:1})]),o("p",null,[n[24]||(n[24]=t("本文由 ",-1)),e(r,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...n[22]||(n[22]=[t("LCTT",-1)])]),_:1}),n[25]||(n[25]=t(" 原创编译，",-1)),e(r,{href:"https://linux.cn/"},{default:p(()=>[...n[23]||(n[23]=[t("Linux中国",-1)])]),_:1}),n[26]||(n[26]=t(" 荣誉推出",-1))])])}const M=a(P,[["render",g]]);export{T as __pageData,M as default};
